<script setup lang="ts">
import {onMounted, ref} from 'vue'
import {request} from './api'
interface Usage {id:string; created_at:string; consumed_points:number; is_free_trial:boolean; external_status:string}
const rows=ref<Usage[]>([]), error=ref(''), busy=ref(false), next=ref<number|null>(null), since=ref(''), until=ref('')
async function load(reset=true){if(busy.value)return;busy.value=true;error.value='';try{const query=new URLSearchParams({offset:String(reset?0:next.value||0)});if(since.value)query.set('since',since.value);if(until.value)query.set('until',until.value);const data=await request<{events:Usage[];next_offset:number|null}>(`/usage?${query}`);rows.value=reset?data.events:rows.value.concat(data.events);next.value=data.next_offset}catch(e){error.value=e instanceof Error?e.message:'无法读取用量'}finally{busy.value=false}}
onMounted(()=>load())
</script>
<template><section class="pc-card"><p class="pc-muted">本页仅查看记录，不执行真实用量上报。</p><form class="pc-toolbar" @submit.prevent="load()"><label>起始日期<input v-model="since" type="date" :disabled="busy" /></label><label>截止日期<input v-model="until" type="date" :disabled="busy" /></label><button :disabled="busy">查询</button></form><p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="!rows.length && !busy">当前范围没有用量记录。</p><table v-if="rows.length"><thead><tr><th>时间</th><th>点数</th><th>类型</th><th>外部确认状态</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td>{{ new Date(row.created_at).toLocaleString() }}</td><td>{{ row.consumed_points }}</td><td>{{ row.is_free_trial?'试用':'额度' }}</td><td>{{ ({none:'无需上报',pending:'待上报',confirmed:'已确认',reporting:'正在确认',unknown:'结果未知'} as Record<string,string>)[row.external_status] || row.external_status }}</td></tr></tbody></table><button v-if="next!==null" :disabled="busy" @click="load(false)">加载更多</button></section></template>
